34	const BASE_PREMIUMS: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
44	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
45	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
46	// (100 * 110) / 100 is exact. Premiums round up in MHPCO's favour at the end.
47	const ONE_HUNDRED_PERCENT = 100;
48	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
49	const ADMIN_FEE = 5;
50	
51	const applyPercent = (amount: number, percent: number): number =>
52	  (amount * percent) / ONE_HUNDRED_PERCENT;
53	
54	const addSurcharge = (amount: number, surchargePercent: number): number =>
55	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
56	
57	const COMPONENT_TYPES = ["rune", "moonstone"];
58	const BUILDING_BLOCK_SIZE = 3;
59	const BUILDING_BLOCK_BASE_PREMIUM = 60;
60	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
61	
62	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
63	
64	// Risk surcharges are per-item properties of the insured object, each raising
65	// that item's premium by a percentage. They stack multiplicatively: an item
66	// matching two rules is surcharged by the first, then by the second.
67	interface RiskSurcharge {
68	  appliesTo: (item: Item) => boolean;
69	  percent: number;
70	}
71	
72	const RISK_SURCHARGES: RiskSurcharge[] = [
73	  { appliesTo: (item) => item.cursed === true, percent: 50 },
74	  { appliesTo: (item) => (item.enchantment ?? 0) >= 5, percent: 30 },
75	];
76	
77	const riskAdjustedPremiumOf = (item: Item): number =>
78	  RISK_SURCHARGES.reduce(
79	    (premium, surcharge) =>
80	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
81	    basePremiumOf(item),
82	  );
83	
84	const sumRiskAdjustedPremiums = (items: Item[]): number =>
85	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
86	
87	// Alike components are grouped into building blocks of 3, which carry a
88	// special base premium; the remaining components are priced individually.
89	// Total over the empty group: no components means no blocks and no remainder.
90	const alikeComponentsBasePremium = (components: Item[]): number => {
91	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
92	  const unblocked = components.slice(blockCount * BUILDING_BLOCK_SIZE);
93	  return (
94	    blockCount * BUILDING_BLOCK_BASE_PREMIUM + sumRiskAdjustedPremiums(unblocked)
95	  );
96	};
97	
98	const groupByType = (items: Item[]): Item[][] => [
99	  ...items
100	    .reduce(
101	      (groups, item) =>
102	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
103	      new Map<string, Item[]>(),
104	    )
105	    .values(),
106	];
107	
108	// Components and main items are priced by different rules, so each group is
109	// totalled separately: components by building block, main items item by item.
110	const componentsBasePremium = (components: Item[]): number =>
111	  groupByType(components).reduce(
112	    (total, alike) => total + alikeComponentsBasePremium(alike),
113	    0,
114	  );
115	
116	const totalBasePremium = (items: Item[]): number =>
117	  sumRiskAdjustedPremiums(items.filter((item) => !isComponent(item))) +
118	  componentsBasePremium(items.filter(isComponent));
119	
120	const quote = (step: QuoteStep): QuoteResult => {
121	  const basePremium = totalBasePremium(step.items);
122	  const premiumAfterFirstInsurance = addSurcharge(
123	    basePremium,
124	    FIRST_INSURANCE_SURCHARGE_PERCENT,
125	  );
126	  return { premium: Math.ceil(premiumAfterFirstInsurance) + ADMIN_FEE };
127	};
128	
129	export const runScenario = (scenario: Scenario): ScenarioResult => ({
130	  results: scenario.steps.map(quote),
131	});
